"""Intent tests for M1-T17: baselines.ScriptedPlayer (BASE-02, TC-19)."""

import json
from pathlib import Path

import numpy as np
import pytest

from rllab.baselines import ScriptedPlayer

FIXTURE = Path(__file__).resolve().parents[2] / "fixtures" / "rllab" / "TC-19"
CASES = ["a", "b", "c", "d"]


def _load(name: str) -> dict:
    return json.loads((FIXTURE / name).read_text())


def _team_obs(values: list[float]) -> np.ndarray:
    return np.asarray([values], dtype=np.float32)


@pytest.mark.intent
@pytest.mark.parametrize("case", CASES)
def test_tc19_scripted_choice(case):
    obs = _load("input.json")["observations"][case]
    expected = _load("expected.json")["actions"][case]
    action = np.asarray(ScriptedPlayer().act(_team_obs(obs), explore=False))
    assert action.shape == (1,)
    assert int(action[0]) == expected


@pytest.mark.intent
@pytest.mark.parametrize("case", CASES)
def test_tc19_scripted_choice_is_deterministic(case):
    obs = _team_obs(_load("input.json")["observations"][case])
    player = ScriptedPlayer()
    first = np.asarray(player.act(obs, explore=False))
    second = np.asarray(ScriptedPlayer().act(obs, explore=False))
    again = np.asarray(player.act(obs, explore=False))
    np.testing.assert_array_equal(first, second)
    np.testing.assert_array_equal(first, again)


@pytest.mark.intent
@pytest.mark.parametrize("width", [5, 10, 12])
def test_non_compact_observation_raises(width):
    obs = np.zeros((1, width), dtype=np.float32)
    with pytest.raises(ValueError, match=r"11"):
        ScriptedPlayer().act(obs, explore=False)

